={
  "model": "llama3.2:3b",
  "prompt": "Eres un asistente que clasifica notas en tickets. Dada esta nota, responde SOLO con JSON valido (sin markdown) con: title (string corto), priority (0-5), project (uno de: FinOps, OfficeAgent, Fotogramia, Homestack, Personal), labels (array de strings). Nota: {{ $json.body.nota }}",
  "stream": false,
  "format": "json"
}

parameters.jsCode:
// Parsea la respuesta de Ollama y mapea proyecto a project_id de Vikunja
const raw = $input.first().json.response;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { title: $('Webhook - Nota entrante').first().json.body.nota.slice(0, 60), priority: 1, project: 'Personal', labels: [] };
}

// Mapa proyecto -> id de Vikunja (ajusta los IDs a los tuyos reales)
const projectMap = {
  'FinOps': 1,
  'OfficeAgent': 2,
  'Fotogramia': 3,
  'Homestack': 4,
  'Personal': 5
};

return {
  title: parsed.title,
  description: $('Webhook - Nota entrante').first().json.body.nota,
  priority: parsed.priority || 1,
  project_id: projectMap[parsed.project] || 5,
  labels: parsed.labels || []
};
